ee:message.ee:set-payload:
%dw 2.0
output application/xml skipNullOn = "everywhere"

ns tem http://tempuri.org/
ns orq http://www.etb.com.co/orquestador
ns orq1 http://schemas.datacontract.org/2004/07/Orquestador.Contracts.Solicitudes

var req = payload.ObtenerDisponibilidadAgendas.solicitudDisponibilidadAgenda
---
{
  tem#ObtenerDisponibilidadAgendas: {
    tem#solicitudDisponibilidadAgenda: {
      orq#DatosSolicitud: {
        orq1#FechaAgenda: (req.DatosSolicitud.FechaAgenda default "") replace "T" with " ",
        orq1#NumeroOrden: req.DatosSolicitud.NumeroOrden default ""
      }
    }
  }
}

%dw 2.0
output application/json

ns tem http://tempuri.org/
ns a http://www.etb.com.co/orquestador

var res = payload.body.tem#ObtenerDisponibilidadAgendasResponse
var resultado = res.tem#Resultado
var agendas = resultado.a#fecha_agendas.*a#DisponibilidadAgenda default []
---
{
  ObtenerDisponibilidadAgendasResponse: {
    Resultado: {
      Encabezado: {
        Servicio: {
          Codigo: resultado.a#Encabezado.a#Servicio.a#Codigo default null,
          DetalleEstado: resultado.a#Encabezado.a#Servicio.a#DetalleEstado default null,
          Estado: resultado.a#Encabezado.a#Servicio.a#Estado default null
        },
        Sistema: {
          Nombre: resultado.a#Encabezado.a#Sistema.a#Nombre default null,
          Servidor: resultado.a#Encabezado.a#Sistema.a#Servidor default null
        }
      },
      fecha_agendas: {
        DisponibilidadAgenda: agendas map (item) -> {
          Zona: item.a#Zona default null,
          color: item.a#color default null,
          date: item.a#date default null,
          quota: item.a#quota default null,
          time_slot: item.a#time_slot default null
        }
      }
    }
  }
}
